'use strict';

/*
 * The check messages reference page (docs/reference/check-messages.md) matches the code. Its one
 * table is generated by scripts/docs-reference.js: the id, the severity and where the check runs
 * come from the check registry (and from BUILD_FINDING_IDS for a finding the build makes outside
 * it); what each message means and what to do come from scripts/docs-reference-text.js. This file
 * holds the literal expectations on the facts, units on scratch inputs, a scan of src/ for finding
 * ids, and a check that the text never advises a flag that is refused.
 *
 * Tests that pass today and so prove nothing on their own (their evidence is the recorded mutation
 * that turns each red): the id list, the source scan and the no-refused-advice test on the real
 * repository. The scratch units and the controls are what show the checks can fail.
 *
 * Residuals the tests cannot see: a finding id built from a variable or a constant (the scan reads
 * only `id: 'area/name'` literals); the build id's severity, which is copied by hand into
 * BUILD_FINDING_IDS; and "check and build", which simplifies `build --no-check`.
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

const gen = require('../scripts/docs-reference');
const textFile = require('../scripts/docs-reference-text');
const { CHECKS } = require('../src/checks/registry');

const ROOT = path.join(__dirname, '..');
const BLOCK = 'check-messages';
const facts = gen.codeFacts()[BLOCK];
const byKey = Object.fromEntries(facts.map((f) => [f.key, f]));

const IDS = [
  'frontmatter/non-yaml-language',
  'frontmatter/parse-error',
  'frontmatter/missing-type',
  'census/type',
  'census/unrecognised-type',
  'census/session-wrap-hub-unpublished',
  'census/session-wrap-link-unpaired',
  'census/session-wrap-learned-missing',
  'staleness/story-behind-pc',
  'link/unresolved',
  'link/in-code',
  'link/ambiguous-target',
  'relationship/missing-required',
  'relationship/unknown-predicate',
  'vault/unmapped-directory',
  'config/exclude-sections-divergence',
  'config/exclude-dirs-divergence',
  'config/exclude-fields-divergence',
  'config/site-vault-path-mismatch',
  'config/pack-shadowed',
  'config/theme-scheme-mismatch',
  'leak/l1-no-manifest',
  'leak/l2-excluded-dir-in-output',
  'leak/l3-unpublished-link',
  'leak/l4-hidden-name',
  'leak/l4-name-collision',
  'leak/l4-output-name',
  'leak/l4-index-term',
  'leak/l5-gm-heading-survives',
  'leak/l6-comment-withheld',
  'leak/l6-comment-unterminated',
  'leak/l6-comment-in-output',
  'graph/orphan',
  'graph/hub-overload',
  'graph/generic-relationship-type',
  'graph/double-stored-edge',
  'build/gm-link-marker',
];

// ---- literal facts the page shows ----

test('the thirty-seven finding ids, as a literal list, registry first and then the build', () => {
  assert.equal(IDS.length, 37);
  assert.deepEqual(facts.map((f) => f.key), IDS);
});

test('severity and where each check runs, for seven ids, as literals', () => {
  const row = (id) => [byKey[id].severity, byKey[id].runs];
  assert.deepEqual(row('leak/l4-hidden-name'), ['ERROR', 'check and build']);
  assert.deepEqual(row('leak/l3-unpublished-link'), ['WARN (varies)', 'check and build']);
  assert.deepEqual(row('leak/l4-index-term'), ['ERROR (varies)', 'check and build']);
  assert.deepEqual(row('config/exclude-dirs-divergence'), ['WARN (varies)', 'check and build']);
  assert.deepEqual(row('census/type'), ['INFO', 'check and build']);
  assert.deepEqual(row('graph/orphan'), ['WARN', 'check --graph only']);
  assert.deepEqual(row('build/gm-link-marker'), ['ERROR', 'build only']);
});

test('the four graph ids are the only ones that need --graph', () => {
  const graph = facts.filter((f) => f.runs === 'check --graph only').map((f) => f.key);
  assert.deepEqual(graph, ['graph/orphan', 'graph/hub-overload', 'graph/generic-relationship-type', 'graph/double-stored-edge']);
});

// ---- checkFacts on scratch inputs, with literal expectations ----

const SCRATCH = [
  { id: 'a/dynamic', defaultSeverity: 'warn', dynamicSeverity: true, requiresFlag: null },
  { id: 'b/flagged', defaultSeverity: 'info', requiresFlag: '--graph' },
  { id: 'c/plain', defaultSeverity: 'error', requiresFlag: null },
];

test('checkFacts gives exact rows for a dynamic, a flagged, a plain and a build id', () => {
  assert.deepEqual(gen.checkFacts({ CHECKS: SCRATCH, buildIds: [{ id: 'd/built', severity: 'error' }] }), [
    { key: 'a/dynamic', severity: 'WARN (varies)', runs: 'check and build' },
    { key: 'b/flagged', severity: 'INFO', runs: 'check --graph only' },
    { key: 'c/plain', severity: 'ERROR', runs: 'check and build' },
    { key: 'd/built', severity: 'ERROR', runs: 'build only' },
  ]);
});

test('checkFacts throws on a duplicate id, in the registry or between the registry and the build ids', () => {
  assert.throws(() => gen.checkFacts({ CHECKS: [...SCRATCH, SCRATCH[2]], buildIds: [] }), /duplicate finding id "c\/plain"/);
  assert.throws(() => gen.checkFacts({ CHECKS: SCRATCH, buildIds: [{ id: 'a/dynamic', severity: 'error' }] }), /duplicate finding id "a\/dynamic"/);
});

test('the real facts come from the registry: every registry entry has a row with its own severity', () => {
  for (const c of CHECKS) {
    const expected = c.defaultSeverity.toUpperCase() + (c.dynamicSeverity ? ' (varies)' : '');
    assert.equal(byKey[c.id].severity, expected, c.id);
  }
});

// ---- the scan of src/ for finding ids, both ways for the build ids ----

const ID_RE = /\bid: '([a-z]+\/[a-z0-9-]+)'/g;
const scanIds = (sources) => {
  const ids = new Set();
  for (const text of sources) for (const m of text.matchAll(ID_RE)) ids.add(m[1]);
  return ids;
};

function srcFiles() {
  const out = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.name.endsWith('.js')) out.push(p);
    }
  };
  walk(path.join(ROOT, 'src'));
  return out;
}

test('control: the scan finds id: \'area/name\' and ignores other shapes', () => {
  const found = scanIds(["const a = { id: 'x/one-two' };\nconst b = { grid: 'y/z' };\nconst c = { id: 'nodash' };\nconst d = { id: \"q/r\" };"]);
  assert.deepEqual([...found], ['x/one-two']);
});

test('every id literal in src/ is a registry id or a build id, and every build id is found in src/', () => {
  const known = new Set([...CHECKS.map((c) => c.id), ...gen.BUILD_FINDING_IDS.map((b) => b.id)]);
  const scanned = scanIds(srcFiles().map((f) => fs.readFileSync(f, 'utf8')));
  const unknown = [...scanned].filter((id) => !known.has(id));
  assert.deepEqual(unknown, [], 'src/ makes a finding id that is neither in CHECKS nor in BUILD_FINDING_IDS (scripts/docs-reference.js): add it, and add its text');
  const notFound = gen.BUILD_FINDING_IDS.map((b) => b.id).filter((id) => !scanned.has(id));
  assert.deepEqual(notFound, [], 'BUILD_FINDING_IDS names an id that src/ no longer makes');
});

test('BUILD_FINDING_IDS is the one build id, frozen', () => {
  assert.deepEqual([...gen.BUILD_FINDING_IDS], [{ id: 'build/gm-link-marker', severity: 'error' }]);
  assert.ok(Object.isFrozen(gen.BUILD_FINDING_IDS));
});

test('the severity copied into BUILD_FINDING_IDS is the one the source gives the finding', () => {
  const src = fs.readFileSync(path.join(ROOT, 'src/build/outputgate.js'), 'utf8');
  const m = /id: 'build\/gm-link-marker',\s*severity: '([a-z]+)'/.exec(src);
  assert.ok(m, 'the gm-link-marker finding was not found in src/build/outputgate.js');
  assert.equal(gen.BUILD_FINDING_IDS[0].severity, m[1]);
});

// ---- the text ----

function allStrings(value, out = []) {
  if (typeof value === 'string') out.push(value);
  else if (value && typeof value === 'object') for (const v of Object.values(value)) allStrings(v, out);
  return out;
}

const REFUSED = /--force(?![-a-z])/;

test('control: the refused-advice pattern matches a bare --force and ignores --force-check and --force-out', () => {
  assert.match('use --force to build', REFUSED);
  assert.match('--force.', REFUSED);
  assert.doesNotMatch('use --force-check or --force-out', REFUSED);
});

test('no check message text advises a bare --force', () => {
  for (const s of allStrings(textFile[BLOCK])) assert.doesNotMatch(s, REFUSED, s);
});

test('the rows for the two refusals nothing overrides say so, and the stale exclude-dirs claim is gone', () => {
  for (const id of ['leak/l6-comment-in-output', 'build/gm-link-marker']) {
    assert.match(textFile[BLOCK][id].what + ' ' + textFile[BLOCK][id].action, /nothing overrides/, id);
  }
  const dirs = textFile[BLOCK]['config/exclude-dirs-divergence'];
  assert.doesNotMatch(dirs.what + ' ' + dirs.action, /only ever reads|never gates/);
  assert.match(dirs.what, /stale build/);
});

test('the exclude-dirs row reads exactly as written and claims no error or refusal (#141)', () => {
  const dirs = textFile[BLOCK]['config/exclude-dirs-divergence'];
  assert.equal(
    dirs.what,
    'A folder is hidden in one config file but not in the other. A fresh build honours both lists, so a folder hidden only in `_meta/vault-config.md` is still left out of a new build. A stale build made before you hid it can still hold its pages, and `leak/l2-excluded-dir-in-output` reports those. This is a WARN when only `_meta/vault-config.md` lists the folder, and an INFO when only `vault.config.json` lists it.',
  );
  assert.equal(
    dirs.action,
    'Add the folder to the list the message says is missing it, so both files agree. This warning never stops a `build`.',
  );
  assert.doesNotMatch(dirs.what, /ERROR|refus/);
  assert.doesNotMatch(dirs.action, /ERROR|refus/);
});

test('every id has a non-empty "what it means" and "what to do"', () => {
  for (const id of IDS) {
    const entry = textFile[BLOCK][id];
    assert.ok(entry, id);
    for (const col of ['what', 'action']) {
      assert.equal(typeof entry[col], 'string', `${id}.${col}`);
      assert.ok(entry[col].trim().length >= 20, `${id}.${col} is too short`);
    }
  }
});

test('the text gives no column the code holds: not severity, not runs', () => {
  for (const [id, entry] of Object.entries(textFile[BLOCK])) {
    assert.equal(entry.severity, undefined, id);
    assert.equal(entry.runs, undefined, id);
  }
});

test('the generator refuses text that gives severity, and text for an unknown id', () => {
  const scratchFacts = { [BLOCK]: [{ key: 'a/b', severity: 'ERROR', runs: 'check and build' }] };
  assert.throws(
    () => gen.rows(BLOCK, { facts: scratchFacts, text: { [BLOCK]: { 'a/b': { what: 'x', action: 'y', severity: 'INFO' } } } }),
    /the code holds "severity", so the text must not give it/,
  );
  assert.throws(
    () => gen.rows(BLOCK, { facts: scratchFacts, text: { [BLOCK]: { 'a/b': { what: 'x', action: 'y' }, 'c/d': { what: 'x', action: 'y' } } } }),
    /has "c\/d" but the code does not/,
  );
});

// ---- the page ----

test('the page renders the five columns, one row per id', () => {
  const lines = gen.renderBlock(BLOCK).split('\n');
  assert.equal(lines[0], '| ID | Severity | Runs in | What it means | What to do |');
  assert.equal(lines.length, 2 + IDS.length);
  assert.match(lines[2], /^\| `frontmatter\/non-yaml-language` \| ERROR \| check and build \| /);
});
